"""probe-e9-pool-listdates — q-e9-pool for family 多因子ML. GENERATED by
study/多因子ML/build-e9-pool-probe.js; edit the builder, not this file.

Question: the listing date of every code hardcoded into 多因子ML's pools —
  ETF_CONFIG['etf_pool'] (14) + WHITE_HORSE_CONFIG['foreign_etfs'] (4, two of them repeats)
  + SMALL_CAP_CONFIG['no_trading_buy'] (1) => 17 unique codes.
Six of them (159525 159628 159652 511090 159934 515180) are undated anywhere in the corpus, so
a point-in-time pool builder must refuse today. This probe replaces the refusal with facts.

Trades NOTHING: SUMMARY `no-trades` is the EXPECTED outcome. The answer travels in the 日志 tab
(`log.error`, so it survives any log-level setting), read with utils/backtest-log.js.
⚠ That endpoint pages at 100 lines regardless of `limit` — page with &offset=.

THREE channels, all logged, so the run is self-diagnosing:
  INIT  get_security_info(c) in initialize, i.e. before the OVERRIDE pins avoid_future_data=True.
        If the runtime answers at all, this is the real start_date including post-window listings.
  FUT   get_all_securities(date=<after the window>) — a second, frame-based route to the same.
  DAY   get_all_securities(date=<each backtest day>) membership. Under avoid_future_data this is
        all that is available, and it can only say "listed by <day>" / "not yet".
CONTROL: 588120 and 513130 carry corpus dates (2023-09-15, 2021-06-01). If the probe reproduces
them the channel is trustworthy; if it does not, nothing else it says may be believed.
"""

CODES = [
    '513100.XSHG',
    '159525.XSHE',
    '513130.XSHG',
    '159915.XSHE',
    '159628.XSHE',
    '588120.XSHG',
    '513520.XSHG',
    '513030.XSHG',
    '518880.XSHG',
    '161226.XSHE',
    '159985.XSHE',
    '501018.XSHG',
    '159652.XSHE',
    '511090.XSHG',
    '159934.XSHE',
    '515180.XSHG',
    '600036.XSHG',
]

FUTURE_DATES = ['2025-12-31', '2026-10-20']

# get_all_securities' type vocabulary is not identical across runtimes, and ONE bad member makes
# the whole call throw — which would cost the fallback channel on every day of the run. Try
# progressively smaller lists and log which one answered.
TYPE_SETS = [
    ['etf', 'lof', 'fund', 'stock'],
    ['etf', 'lof', 'stock'],
    ['etf', 'stock'],
    ['etf'],
]


def _frame(d):
    last = None
    for ts in TYPE_SETS:
        try:
            df = get_all_securities(ts, date=d)
            return df, '+'.join(ts)
        except Exception as e:
            last = e
    raise last


def _emit(tag, c, info):
    if info is None:
        log.error('%s\t%s\tNONE' % (tag, c))
        return False
    try:
        log.error('%s\t%s\t%s\t%s\t%s' % (tag, c, info.start_date, info.end_date,
                                             info.display_name))
    except Exception as e:
        log.error('%s\t%s\tPARTIAL\t%s' % (tag, c, e))
    return True


def initialize(context):
    set_benchmark('000300.XSHG')
    set_option('use_real_price', True)
    # NOT setting avoid_future_data here — see the builder's header. The OVERRIDE sets it after
    # this function returns, so these lookups run at the runtime default.
    g.pending = []
    g.first = True
    log.error('PROBE-BEGIN\tn=%d' % len(CODES))

    for c in CODES:
        try:
            info = get_security_info(c)
        except Exception as e:
            log.error('INIT\t%s\tEXC\t%s' % (c, e))
            g.pending.append(c)
            continue
        if not _emit('INIT', c, info):
            g.pending.append(c)

    for d in FUTURE_DATES:
        try:
            df, used = _frame(d)
            log.error('FUT-TYPES\t%s\t%s' % (d, used))
            idx = set(df.index)
            hits = 0
            for c in CODES:
                if c in idx:
                    hits += 1
                    log.error('FUT\t%s\t%s\t%s' % (d, c, df.loc[c, 'start_date']))
                else:
                    log.error('FUT\t%s\t%s\tABSENT' % (d, c))
            log.error('FUT-END\t%s\thits=%d/%d' % (d, hits, len(CODES)))
        except Exception as e:
            log.error('FUT-EXC\t%s\t%s' % (d, e))

    log.error('INIT-END\tpending=%s' % (','.join(g.pending) or '-'))
    run_daily(check, '09:31')


def check(context):
    d = context.current_dt.date()
    try:
        df, used = _frame(d)
        idx = set(df.index)
    except Exception as e:
        log.error('DAY-EXC\t%s\t%s' % (d, e))
        return
    # Day 1 logs every code (an independent cross-check of INIT); later days only the unresolved,
    # to keep the 100-line log pages legible.
    todo = CODES if g.first else list(g.pending)
    g.first = False
    still = []
    for c in todo:
        if c in idx:
            try:
                sd = str(df.loc[c, 'start_date'])
            except Exception:
                sd = '?'
            log.error('DAY\t%s\t%s\tIN\t%s' % (d, c, sd))
        else:
            log.error('DAY\t%s\t%s\tOUT\t-' % (d, c))
            still.append(c)
    # still is always a subset of todo, and on day 1 todo is every code, so this is correct for
    # both branches: whatever is NOT yet listed stays pending.
    g.pending = still
    log.error('DAY-END\t%s\ttypes=%s\tlisted=%d/%d\tpending=%s'
              % (d, used, len(idx & set(CODES)), len(CODES), ','.join(g.pending) or '-'))



# ===== AUTORESEARCH NORMALIZATION OVERRIDE (appended; strategies/ file untouched) =====
# harness/harness.md §2 — force the frozen execution settings regardless of what the
# raw strategy sets, even if it re-sets costs every bar. Values are pinned in
# harness/config/epoch-<n>.json; utils/harness-config.js --verify checks this block
# still matches, because Python running on JQ's servers cannot read that JSON.
__jq_set_slippage = set_slippage
def set_slippage(*a, **k):
    __jq_set_slippage(FixedSlippage(0))
__jq_set_commission = set_commission
def set_commission(*a, **k):
    __jq_set_commission(PerTrade(buy_cost=0.0003, sell_cost=0.0013, min_cost=5))
# epoch 4: set_commission does NOT govern funds, so 170 held strategies were running
# ETF trades on their own costs. Pin the fund table too, and neutralise re-sets.
# epoch 6: it does not govern STOCKS either. JQ deprecated set_commission in favour of
# set_order_cost, so a strategy's own type='stock' call won outright and 95 of 215 held
# strategies were being charged their AUTHOR's fees. Measured by probe: a 5%/side stock
# commission injected into int-001 moved total return +64.44% -> -11.33% (-75.77pp), i.e.
# the bench had no control over stock fees at all. Both tables are now pinned, and the
# fall-through forwards only the types we do not model (futures, mmf, ...).
# Guarded: unlike set_slippage/set_commission, set_order_cost is NOT bound at module
# scope in every JQ runtime — rebinding it unguarded raised NameError at import and
# the whole strategy came back compile-error.
try:
    __jq_set_order_cost = set_order_cost
    def __jq_cost_type(a, k):
        t = k.get('type')
        if t is None and len(a) > 1:
            t = a[1]
        return t
    def set_order_cost(*a, **k):
        __t = __jq_cost_type(a, k)
        if __t == 'fund':
            __jq_set_order_cost(OrderCost(open_commission=0.0003, close_commission=0.0003, close_tax=0, min_commission=5), type='fund')
        elif __t == 'stock':
            __jq_set_order_cost(OrderCost(open_commission=0.0003, close_commission=0.0003, close_tax=0.001, min_commission=5), type='stock')
        else:
            __jq_set_order_cost(*a, **k)
except NameError:
    pass
try:
    __jq_orig_initialize = initialize
    def initialize(context):
        __jq_orig_initialize(context)
        set_option('use_real_price', True)
        # epoch 4 pins, applied AFTER the strategy's own initialize so they win
        set_option('avoid_future_data', True)
        set_option('order_volume_ratio', 0.05)
        set_slippage(FixedSlippage(0))
        set_commission(PerTrade(buy_cost=0.0003, sell_cost=0.0013, min_cost=5))
        try:
            set_order_cost(OrderCost(open_commission=0.0003, close_commission=0.0003, close_tax=0, min_commission=5), type='fund')
        except Exception:
            pass
        # epoch 6: pin the stock table too, AFTER the strategy's own initialize so it wins
        # even when the strategy set its costs there rather than at module scope.
        try:
            set_order_cost(OrderCost(open_commission=0.0003, close_commission=0.0003, close_tax=0.001, min_commission=5), type='stock')
        except Exception:
            pass
except NameError:
    pass
# ===== END OVERRIDE =====

